(()=>{'use strict';
const cfg=window.CARDBOARD_CLINIC_CONFIG||{};
const LIVE=!!(cfg.supabaseUrl&&cfg.supabaseAnonKey&&window.supabase);
const db=LIVE?window.supabase.createClient(cfg.supabaseUrl,cfg.supabaseAnonKey):null;
const USD='SGD';
const STAGES=['Registered','Intake & Photography','Initial Inspection','Diagnosis & Treatment Plan','Awaiting Client Signature','Form Verified','Payment Received','Treatment Scheduled','Treatment In Progress','Quality Control','Final Documentation','Ready for Return'];
const PRICE_DEFAULT=[
{code:'assessment',label:'Preliminary Photo Assessment',detail:'Initial visual opinion from supplied photos',base:0,category:'care',sort_order:1},
{code:'report',label:'Physical Condition Report',detail:'Written inspection and treatment recommendations',base:15,category:'care',sort_order:2},
{code:'surface',label:'Surface Cleaning',detail:'Dust and accessible surface contamination',base:25,category:'care',sort_order:3},
{code:'residue',label:'Residue / Adhesive Removal',detail:'Case-dependent accessible adhesive residue',base:35,category:'care',sort_order:4},
{code:'edge',label:'Edge / Corner Lift Reduction',detail:'Lifted layers; not whitening or lost print',base:40,category:'restore',sort_order:5},
{code:'warp',label:'Warping / Curling Treatment',detail:'Case-by-case shape and curl assessment',base:45,category:'restore',sort_order:6},
{code:'dent',label:'Dent / Indent Reduction',detail:'Pressure marks and small dings',base:50,category:'restore',sort_order:7},
{code:'crease',label:'Minor Crease Reduction',detail:'Visible fold or crease; outcomes vary',base:70,category:'restore',sort_order:8},
{code:'complex',label:'Complex Crease / Layer Separation',detail:'Specialist treatment; custom above baseline',base:100,category:'restore',sort_order:9},
{code:'slab',label:'Graded Slab Extraction',detail:'Removal only with owner consent and accepted risk',base:20,category:'care',sort_order:10}
];
const TIER_DEFAULT=[{id:1,min_value:0,max_value:199.99,multiplier:1,label:'Below S$200'},{id:2,min_value:200,max_value:999.99,multiplier:1.2,label:'S$200–S$999'},{id:3,min_value:1000,max_value:4999.99,multiplier:1.5,label:'S$1,000–S$4,999'},{id:4,min_value:5000,max_value:null,multiplier:null,label:'S$5,000+'}];
const SETTINGS_DEFAULT={capacity:25,weekly_rate:5,historical_completed:53};
const DEMO_CASES=[];
const DEMO_UPDATES=[];
const $=s=>document.querySelector(s);const $$=s=>[...document.querySelectorAll(s)];
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=n=>Number(n).toLocaleString('en-SG',{style:'currency',currency:'SGD',maximumFractionDigits:2});
const date=s=>s?new Date(s).toLocaleDateString('en-SG',{year:'numeric',month:'short',day:'numeric'}):'—';
const uid=()=>crypto?.randomUUID?.()||('demo-'+Date.now().toString(16));
const loadLocal=(key,def)=>{try{const x=JSON.parse(localStorage.getItem('cc_'+key));return x??def}catch{return def}};
const saveLocal=(key,x)=>{try{localStorage.setItem('cc_'+key,JSON.stringify(x))}catch(e){console.warn('Demo local storage unavailable',e)}};
let prices=loadLocal('prices',PRICE_DEFAULT).sort((a,b)=>a.sort_order-b.sort_order);
let tiers=loadLocal('tiers',TIER_DEFAULT);let settings=loadLocal('settings',SETTINGS_DEFAULT);
try{if(localStorage.getItem('cc_demo_wiped')!=='1'){Object.keys(localStorage).filter(k=>k.startsWith('cc_')&&k!=='cc_intro_played').forEach(k=>localStorage.removeItem(k));localStorage.setItem('cc_demo_wiped','1')}}catch(e){}
let cases=loadLocal('cases',DEMO_CASES),updates=loadLocal('updates',DEMO_UPDATES),decisions=loadLocal('decisions',[]),photos=loadLocal('photos',[]),reviews=loadLocal('reviews',[]);
let consents=loadLocal('consents',[]);let portfolio=loadLocal('portfolio',[]),historicalCount=loadLocal('historicalCount',53),publicClosedCount=0;let user=null,isStaff=false,demoActor=null,activeCaseId=null,adminTab='overview';let connectionError='';

function persist(){if(LIVE)return;[['prices',prices],['tiers',tiers],['settings',settings],['cases',cases],['updates',updates],['decisions',decisions],['photos',photos],['reviews',reviews],['portfolio',portfolio],['consents',consents],['historicalCount',historicalCount]].forEach(([k,v])=>saveLocal(k,v))}
function treatment(code){return prices.find(x=>x.code===code)||{label:code,base:0,category:'care'}}
function valueTier(n){return tiers.find(x=>n>=Number(x.min_value)&& (x.max_value==null||n<=Number(x.max_value)))||tiers[tiers.length-1]}
function priceFor(code,value){const t=treatment(code),band=valueTier(Number(value)||0);if(t.category==='restore'&&band.multiplier==null)return null;return Math.round((Number(t.base)||0)*(t.category==='restore'?Number(band.multiplier):1)*100)/100}
function estimateTreatments(codes,value){const vals=codes.map(code=>priceFor(code,value));return vals.includes(null)?null:Math.round(vals.reduce((a,b)=>a+b,0)*100)/100}
function setMessage(el,msg,error=false){const n=typeof el==='string'?$(el):el;if(!n)return;n.innerHTML=msg?`<div class="form-message ${error?'error':''}" role="status">${esc(msg)}</div>`:''}
const gpPicked=new Set();let gpValue=350,gpPriority=false;
function renderGlassPricing(rows){const grid=document.getElementById('gpGrid');if(!grid)return;
const fmt=n=>money(n).replace('.00','');
grid.innerHTML=`<div class="gp-table">
<div class="gp-tool"><label class="gp-value"><span>Your card's current value</span><span class="gp-input"><em>S$</em><input id="gpValue" type="number" inputmode="decimal" min="0" step="10" value="${gpValue}" aria-describedby="gpBand"></span></label><span class="gp-band" id="gpBand"></span><span class="gp-hint">Tick everything your card needs. Your estimate updates below.</span></div>
<div class="gp-thead"><span></span><span>Treatment</span><span>Category</span><span>Price for your card</span></div>
${rows.map(x=>`<label class="gp-row"><input class="gp-check" type="checkbox" value="${esc(x.code)}" ${gpPicked.has(x.code)?'checked':''}><i class="gp-box" aria-hidden="true"></i><span class="gp-t"><strong>${esc(x.label)}</strong><small>${esc(x.detail)}</small></span><span class="gp-cat ${x.category==='restore'?'is-restore':'is-care'}">${x.category==='restore'?'Structural':'Care / Other'}</span><b class="gp-p" data-code="${esc(x.code)}"></b></label>`).join('')}
<label class="gp-row gp-priority"><input class="gp-check" type="checkbox" id="gpPriority" ${gpPriority?'checked':''}><i class="gp-box" aria-hidden="true"></i><span class="gp-t"><strong>Priority queue</strong><small>Optional faster scheduling, once per card · subject to an available slot</small></span><span class="gp-cat">Add-on</span><b class="gp-p">+ ${fmt(75)}</b></label>
<div class="gp-total"><div><span class="gp-total-label">Your estimate</span><small id="gpCount">Nothing selected yet</small></div><strong id="gpTotal">S$0</strong><a class="gp-btn gp-btn-solid" href="https://wa.me/6598221113?text=Hi%20Cardboard%20Clinic%2C%20I%27d%20like%20a%20free%20assessment.%20Here%20are%20photos%20of%20my%20card%3A" target="_blank" rel="noopener">Send us photos</a></div>
<p class="gp-small">SGD per card. Starting rates for one issue each; complex cases need diagnosis. A guide, not a final quote. We confirm the price after seeing your card.</p>
</div>`;
gpUpdate();
const t=document.getElementById('gpTiers');if(t)t.innerHTML=tiers.map(x=>`<span><em>${esc(x.label)}</em>${x.multiplier==null?'Custom quote':'×'+Number(x.multiplier).toFixed(2)}</span>`).join('');
if(!grid.dataset.bound){grid.dataset.bound='1';
  grid.addEventListener('change',e=>{const el=e.target;if(el.id==='gpPriority')gpPriority=el.checked;else if(el.classList.contains('gp-check')){el.checked?gpPicked.add(el.value):gpPicked.delete(el.value)}gpUpdate()});
  grid.addEventListener('input',e=>{if(e.target.id==='gpValue'){gpValue=Math.max(0,Number(e.target.value)||0);gpUpdate()}});}
}
function gpUpdate(){const rows=prices.filter(x=>x.active!==false);const fmt=n=>money(n).replace('.00','');const band=valueTier(gpValue);
$$('#gpGrid .gp-p[data-code]').forEach(el=>{const c=el.dataset.code,t=treatment(c),p=priceFor(c,gpValue);el.textContent=p==null?'Custom quote':(Number(t.base)===0?'Free':fmt(p)+(c==='complex'?'+':''));el.classList.toggle('is-custom',p==null)});
const bandEl=document.getElementById('gpBand');if(bandEl)bandEl.innerHTML=band.multiplier==null?'Structural work: <b>custom quote</b> at this value':`Structural work: <b>×${Number(band.multiplier).toFixed(2)}</b> (${esc(band.label)})`;
const picked=rows.filter(x=>gpPicked.has(x.code));const amounts=picked.map(x=>priceFor(x.code,gpValue));const custom=amounts.some(a=>a==null);
const sum=amounts.filter(a=>a!=null).reduce((s,a)=>s+a,0)+(gpPriority?75:0);
const total=document.getElementById('gpTotal'),count=document.getElementById('gpCount');if(!total)return;
total.textContent=custom?'Custom quote':(!picked.length&&!gpPriority?'S$0':fmt(sum)+(picked.some(x=>x.code==='complex')?'+':''));
const n=picked.length;count.textContent=n||gpPriority?`${n} treatment${n===1?'':'s'}${gpPriority?' + priority':''} selected`:'Nothing selected yet';}
function renderPublic(){const rows=prices.filter(x=>x.active!==false).sort((a,b)=>a.sort_order-b.sort_order);renderGlassPricing(rows);
$('#priceTable').innerHTML=rows.map(x=>`<tr><td>${esc(x.label)}<small>${esc(x.detail)}</small></td><td><span class="tag ${x.category==='restore'?'risk':'care'}">${x.category==='restore'?'Structural':'Care / Other'}</span></td><td>${money(x.base)}${x.code==='complex'?'+':''}</td></tr>`).join('');
$('#valueTable').innerHTML=tiers.map(x=>`<tr><td>${esc(x.label)}</td><td>${x.multiplier==null?'Custom quotation':Number(x.multiplier).toFixed(2)+'× base price'}</td></tr>`).join('');
const checked=new Set($$('#calcTreatments input:checked').map(el=>el.value));const selected=checked.size?checked:new Set(['dent']);$('#calcTreatments').innerHTML=rows.filter(x=>x.code!=='assessment').map(x=>`<label class="alacarte-item"><input type="checkbox" value="${esc(x.code)}" ${selected.has(x.code)?'checked':''}><span class="treat-label">${esc(x.label)}<small>${x.category==='restore'?'Structural · card value applies':'Flat-rate service'}</small></span><span class="treat-price">From ${money(x.base)}</span></label>`).join('');calc();renderQueue();renderReviews();renderPortfolio();renderRestoredCount()}
function calc(){const v=Math.max(0,Number($('#calcValue').value)||0),band=valueTier(v);const codes=$$('#calcTreatments input:checked').map(x=>x.value);const lines=codes.map(c=>({item:treatment(c),amount:priceFor(c,v)}));const anyCustom=lines.some(x=>x.amount==null);const priority=$('#calcPriority').checked;const subtotal=lines.filter(x=>x.amount!=null).reduce((sum,x)=>sum+x.amount,0)+(priority?75:0);$('#calcBreakdown').innerHTML=lines.length?lines.map(({item,amount})=>`<div class="calc-line"><span>${esc(item.label)}${item.category==='restore'&&band.multiplier!=null?' <small>('+Number(band.multiplier).toFixed(2)+'×)</small>':''}</span><strong>${amount==null?'Custom quote':money(amount)+(item.code==='complex'?'+':'')}</strong></div>`).join(''):'<div class="calc-empty">Select treatments above to build your estimate.</div>';if(priority)$('#calcBreakdown').innerHTML+='<div class="calc-line"><span>Priority Queue <small>(per card)</small></span><strong>S$75.00</strong></div>';$('#calcEstimate').textContent=!lines.length&&!priority?'S$0.00':anyCustom?'Custom quote':money(subtotal)+(lines.some(x=>x.item.code==='complex')?'+':'');$('#calcMultiplier').textContent=!lines.length?(priority?'Priority Queue only · staff confirmation required':'No treatments selected'):anyCustom?`${money(subtotal)} known charges + specialist quotation required`:lines.some(x=>x.item.category==='restore')?`${Number(band.multiplier).toFixed(2)}× on structural work only · ${lines.length} item${lines.length===1?'':'s'}`:`${lines.length} flat-rate item${lines.length===1?'':'s'} · no value multiplier`}
function renderQueue(){const active=cases.filter(x=>!x.closed_at).length,cap=Math.max(1,Number(settings.capacity)||25),rate=Math.max(1,Number(settings.weekly_rate)||5);const gap=Math.max(0,Math.ceil(active/rate));$('#queueMode').textContent='';$('#queueCount').innerHTML=`${active} <span>/ ${cap} slots</span>`;$('#queueFill').style.width=`${Math.min(100,active/cap*100)}%`;$('#queueStatus').textContent=active>=cap?'Intake currently at capacity':'Limited intake availability';$('#queueAvailable').textContent=`${Math.max(0,cap-active)} available`;
$('#queueWait').textContent=active===0?'Enquire now':`Approx. ${gap}–${gap+1} weeks`;$('#queueRate').textContent=`Approx. ${rate} cards / week`;$('#queueFootnote').textContent=LIVE?'Priority intake is limited and confirmed by staff. Live caseload; estimates are non-binding and subject to case complexity.':'Waiting times are estimates and depend on each card.'}
function renderRestoredCount(){
 const closed=LIVE?publicClosedCount:new Set(cases.filter(c=>c.closed_at).map(c=>c.id)).size;
 const total=Math.max(0,Number(historicalCount)||0)+closed;
 $('#restoredCount').innerHTML=`${total.toLocaleString('en-SG')}<small>Cards repaired &amp; restored</small>`;
 $('#restoredSource').textContent=LIVE?'Historical record + completed card cases':'Cards repaired and restored';
}
function portfolioImage(path){
 if(!path)return '';
 if(LIVE)return db.storage.from('portfolio-public').getPublicUrl(path).data.publicUrl;
 return /^data:image\/(?:jpeg|png|webp);base64,/.test(path)?path:'';
}
function renderPortfolio(){
 const published=portfolio.filter(p=>p.is_published);
 $('#portfolioGrid').innerHTML=published.length?published.map(p=>`<article class="portfolio-tile"><div class="portfolio-photos">${[['Before',p.before_path],['After',p.after_path]].map(([label,path])=>`<div class="portfolio-photo"><img loading="lazy" src="${esc(portfolioImage(path))}" alt="${esc(p.card_name)} ${label.toLowerCase()}"><b>${label}</b></div>`).join('')}</div><div class="portfolio-copy"><h3>${esc(p.card_name)}</h3><p><b>Starting condition:</b> ${esc(p.issue_summary)}</p><p><b>Care provided:</b> ${esc(p.treatment_summary)}</p><p>${esc(p.outcome_notes)}</p></div></article>`).join(''):'<div class="portfolio-empty"><h3>Real cards. Individual stories.</h3><p style="margin-bottom:0">Before-and-after cases will appear here once the owner has given permission to share them. Every result is individual.</p></div>';
}
function portfolioAdmin(){return `<div class="panel"><h3>Cards repaired &amp; restored</h3><p>Start with the 53 cards already completed. New closed card records add once each. Do not include the same cards in both the historical total and new records.</p><form id="historicalForm"><label class="field"><span>Previously completed cards</span><input type="number" min="0" step="1" name="historical_count" value="${Number(historicalCount)||0}" required></label><button class="btn gold small" type="submit" style="margin-top:15px">Save starting count</button><div id="historicalMsg"></div></form></div><div class="panel"><h3>Share a completed card’s story</h3><p>Use photos you have permission to publish. These images become public. Keep private names, case references and contact details out of the photos and description.</p><form id="portfolioForm"><div class="form-grid"><label class="field span2"><span>Card name *</span><input name="card_name" required></label><label class="field span2"><span>Starting condition *</span><textarea name="issue_summary" required></textarea></label><label class="field span2"><span>Care provided *</span><textarea name="treatment_summary" required></textarea></label><label class="field span2"><span>Outcome and remaining limitations</span><textarea name="outcome_notes" placeholder="Describe the individual result without promising a grade."></textarea></label><label class="field"><span>Before photo *</span><input type="file" name="before_image" accept="image/jpeg,image/png,image/webp" required></label><label class="field"><span>After photo *</span><input type="file" name="after_image" accept="image/jpeg,image/png,image/webp" required></label></div><label class="check-label" style="margin-top:15px"><input name="permission" type="checkbox" required> I have the owner’s permission to publish these photos and have removed private information.</label><button class="btn gold" type="submit" style="margin-top:20px">Publish card story</button><div id="portfolioMsg"></div></form></div><div class="panel"><h3>Portfolio stories</h3><div class="portfolio-admin-list">${portfolio.map(p=>`<div class="portfolio-admin-entry"><div><b>${esc(p.card_name)}</b><div class="statusline">${p.is_published?'Published':'Unpublished'}</div></div><button class="btn ghost small" data-toggle-portfolio="${esc(p.id)}">${p.is_published?'Unpublish':'Publish'}</button></div>`).join('')||'<div class="empty">No stories added yet.</div>'}</div></div>`;}
async function publishPortfolio(form){
 if(!(isStaff||(!LIVE&&demoActor?.staff)))throw Error('Staff access required.');
 if(!form.permission.checked)throw Error('Confirm owner permission before publishing.');
 const fd=new FormData(form),obj={card_name:String(fd.get('card_name')).trim(),issue_summary:String(fd.get('issue_summary')).trim(),treatment_summary:String(fd.get('treatment_summary')).trim(),outcome_notes:String(fd.get('outcome_notes')||'').trim(),is_published:true};
 for(const phase of ['before','after']){
  const file=fd.get(phase+'_image');if(!file?.size||!/^image\/(jpeg|png|webp)$/.test(file.type))throw Error('Choose a JPEG, PNG or WebP photo for each view.');if(file.size>8*1024*1024)throw Error('Photos must be smaller than 8 MB.');
  if(LIVE){const ext={ 'image/jpeg':'jpg','image/png':'png','image/webp':'webp'}[file.type],path=`${uid()}-${phase}.${ext}`;const {error}=await db.storage.from('portfolio-public').upload(path,file,{contentType:file.type,upsert:false});if(error)throw error;obj[phase+'_path']=path;}
  else obj[phase+'_path']=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=()=>reject(Error('Unable to read photo.'));reader.readAsDataURL(file);});
 }
 if(LIVE){const {data,error}=await db.from('restoration_portfolio').insert(obj).select().single();if(error)throw error;portfolio.unshift(data);}else portfolio.unshift({...obj,id:uid(),created_at:new Date().toISOString()});
 persist();renderPortfolio();
}

function renderReviews(){const list=reviews.filter(x=>x.is_published);const initial=n=>esc(String(n||'?').trim().charAt(0).toUpperCase());$('#reviewList').innerHTML=list.length?list.map(x=>`<article class="rv-card"><p class="rv-text">${esc(x.review_text)}</p><div class="rv-who"><span class="rv-avatar" aria-hidden="true">${initial(x.display_name)}</span><span><strong>${esc(x.display_name)}</strong><small>${esc(x.review_source||'Previously received review')}</small></span></div></article>`).join(''):`<article class="rv-card rv-empty"><p class="rv-text">Collector reviews will appear here once clients give permission to share them.</p><div class="rv-who"><span class="rv-avatar" aria-hidden="true">CC</span><span><strong>Cardboard Clinic</strong><small>No example or invented reviews are shown</small></span></div></article>`;document.dispatchEvent(new Event('reviews:rendered'))}
function route(){const hash=location.hash.replace('#','')||'home';const view=['portal','admin','portfolio','privacy','terms'].includes(hash)?hash:'public';['public','portal','admin','portfolio','privacy','terms'].forEach(k=>$(`#${k}View`).hidden=k!==view);$('#navlinks').classList.remove('open');$('#mobileNav').setAttribute('aria-expanded','false');if(view==='portal')renderPortal();if(view==='admin')renderAdmin();if(view!=='public'||hash==='home')window.scrollTo({top:0,behavior:'instant'});else setTimeout(()=>document.getElementById(hash)?.scrollIntoView({behavior:'smooth'}),50)}
const realEmail=()=>LIVE?String(user?.email||'').toLowerCase():String(demoActor?.email||'').toLowerCase();
let authMode='signin';
function authField(label,name,type,auto,min){return `<label class="au-field"><span>${label}</span><input name="${name}" type="${type}" autocomplete="${auto}" required ${min?`minlength="${min}"`:''} placeholder="${label}"></label>`}
function portalAuthForm(){const back=`<p class="au-links"><a href="#portal" data-authmode="signin">‹ Back to sign in</a></p>`;
if(authMode==='sent')return `<div class="au-done"><svg class="au-check" viewBox="0 0 64 64" aria-hidden="true"><rect x="3" y="3" width="58" height="58"/><path d="M18 33l10 10 19-22"/></svg><h3>Check your email</h3><p>We sent a confirmation link to <strong>${esc(authEmail)}</strong>. Open it, then sign in here to see your cards.</p><a class="au-btn" href="#portal" data-authmode="signin">Back to sign in</a></div>`;
if(authMode==='signup')return `<form id="portalSignup" class="au-form">${authField('Email address','email','email','email')}${authField('Create password','password','password','new-password',8)}${authField('Confirm password','password2','password','new-password',8)}<div id="portalLoginMsg"></div><button class="au-btn" type="submit"><span>Create account</span></button>${back}</form>`;
if(authMode==='reset')return `<form id="portalReset" class="au-form">${authField('Email address','email','email','email')}<div id="portalLoginMsg"></div><button class="au-btn" type="submit"><span>Email me a reset link</span></button>${back}</form>`;
return `<form id="portalNewPassword" class="au-form">${authField('New password','password','password','new-password',8)}<div id="portalLoginMsg"></div><button class="au-btn" type="submit"><span>Save new password</span></button></form>`}
let authEmail='';
function authFlipTo(mode){const card=document.querySelector('#portalContent .au-card');const still=matchMedia('(prefers-reduced-motion: reduce)').matches;
if(!card||still){authMode=mode;renderPortal();return}
card.classList.add('au-flip-out');setTimeout(()=>{authMode=mode;renderPortal();const n=document.querySelector('#portalContent .au-card');if(n)n.classList.add('au-flip-in')},260)}

const authRedirect=()=>location.origin+location.pathname+'#portal';
async function portalSignup(f){const email=f.email.value.trim();if(f.password.value!==f.password2.value)throw Error('Passwords do not match.');if(!LIVE)throw Error('Accounts are opening soon. For an update on your card, WhatsApp us on 9822 1113.');const {data,error}=await db.auth.signUp({email,password:f.password.value,options:{emailRedirectTo:authRedirect()}});if(error){if(/rate limit/i.test(error.message))throw Error('Too many sign-ups right now. Please try again in a few minutes, or WhatsApp us on 9822 1113.');throw error}if(data.session){user=data.user;authMode='signin';await checkStaff();await refreshCases();renderPortal();return}authEmail=email;authFlipTo('sent')}
async function portalReset(f){const {error}=await db.auth.resetPasswordForEmail(f.email.value.trim(),{redirectTo:authRedirect()});if(error){if(/rate limit/i.test(error.message))throw Error('Too many reset emails right now. Please try again in a few minutes.');throw error}f.reset();setMessage('#portalLoginMsg','If that email has an account, a reset link is on its way.')}
async function portalNewPassword(f){const {data,error}=await db.auth.updateUser({password:f.password.value});if(error)throw error;user=data.user;authMode='signin';await checkStaff();await refreshCases();renderPortal()}
function loginMarkup(kind){const isPortal=kind==='portal';
const titles={signin:isPortal?'Sign in to your card tracker':'Staff sign in',signup:'Create your account',reset:'Reset your password',newpass:'Choose a new password',sent:''};
const subs={signin:isPortal?'Use the same email you gave the clinic for your cards.':'Authorised staff only.',signup:'Use the same email you gave the clinic, so your cards appear automatically.',reset:'Enter your email and we will send you a reset link.',newpass:'Enter a new password for your account.',sent:''};
const mode=isPortal?authMode:'signin';
const body=isPortal&&mode!=='signin'?portalAuthForm():`<form id="${kind}Login" class="au-form">${authField('Email address','email','email','email')}${authField('Password','password','password','current-password',6)}${isPortal?`<p class="au-forgot"><a href="#portal" data-authmode="reset">Forgot password?</a></p>`:''}<div id="${kind}LoginMsg"></div><button class="au-btn" type="submit"><span>Sign in</span></button>${isPortal?`<p class="au-links">New here? <a href="#portal" data-authmode="signup">Create an account</a></p>`:''}</form>`;
return `<div class="signin au-wrap"><div class="au-card au-mode-${mode}"><img class="au-logo" src="assets/logo.png" width="208" height="73" alt="Cardboard Clinic">${titles[mode]?`<h3>${titles[mode]}</h3><p class="au-sub">${subs[mode]}</p>`:''}${body}</div><a class="au-home" href="#home" data-view="public">‹ Back to website</a></div>`}

async function signIn(kind,form){if(!LIVE){setMessage(`#${kind}LoginMsg`,'Accounts are opening soon. For an update on your card, WhatsApp us on 9822 1113.',true);return}const email=form.email.value.trim(),pass=form.password.value;setMessage(`#${kind}LoginMsg`,'');const b=form.querySelector('[type=submit]');b.disabled=true;try{const {data,error}=await db.auth.signInWithPassword({email,password:pass});if(error)throw error;user=data.user;await checkStaff();if(kind==='admin'&&!isStaff){await db.auth.signOut();user=null;throw new Error('This account does not have staff permissions.')}await refreshCases();if(kind==='portal'&&isStaff){location.hash='#admin';return}kind==='admin'?renderAdmin():renderPortal()}catch(e){setMessage(`#${kind}LoginMsg`,e.message||'Unable to sign in.',true)}finally{b.disabled=false}}
async function checkStaff(){if(!LIVE||!user){isStaff=false;return}const {data,error}=await db.from('staff').select('user_id').eq('user_id',user.id).maybeSingle();isStaff=!error&&!!data}
async function signOut(){if(LIVE){await db.auth.signOut();user=null;isStaff=false;cases=[];updates=[];photos=[];decisions=[]}else demoActor=null;renderPortal();renderAdmin();renderQueue()}
async function refreshCases(){if(!LIVE)return;if(isStaff){const {data:allPortfolio,error:portfolioError}=await db.from('restoration_portfolio').select('*').order('created_at',{ascending:false});if(!portfolioError)portfolio=allPortfolio||[];}const query=isStaff?db.from('cards').select('*').order('created_at',{ascending:false}):db.from('cards').select('*').order('created_at',{ascending:false});const {data,error}=await query;if(error)throw error;cases=data||[];const ids=cases.map(x=>x.id);updates=[];photos=[];decisions=[];consents=[];if(ids.length){const [u,p,d,a]=await Promise.all([db.from('case_updates').select('*').in('case_id',ids).order('created_at',{ascending:false}),db.from('case_photos').select('*').in('case_id',ids).order('created_at',{ascending:false}),db.from('quote_decisions').select('*').in('case_id',ids).order('created_at',{ascending:false}),db.from('case_consents').select('*').in('case_id',ids).order('created_at',{ascending:false})]);updates=u.data||[];photos=p.data||[];decisions=d.data||[];consents=a.data||[]}}
async function refreshPublic(){if(!LIVE){renderPublic();return}try{const [p,t,s,r]=await Promise.all([db.from('pricing_services').select('*').order('sort_order'),db.from('pricing_tiers').select('*').order('id'),db.from('clinic_settings').select('*').eq('id',1).maybeSingle(),db.from('client_reviews').select('*').eq('is_published',true).order('created_at',{ascending:false})]);
if(p.error||t.error||s.error||r.error)throw p.error||t.error||s.error||r.error;
prices=p.data||[];tiers=t.data||[];settings=s.data||SETTINGS_DEFAULT;reviews=r.data||[];historicalCount=Number(settings.historical_completed??53);
// The public RLS cannot read private cards. A SECURITY DEFINER aggregate function is required.
const count=await db.rpc('public_queue_count');if(count.error)throw count.error;
window.__publicQueueCount=Number(count.data)||0;const [cDone,port]=await Promise.all([db.rpc('public_completed_count'),db.from('restoration_portfolio').select('*').eq('is_published',true).order('created_at',{ascending:false})]);if(cDone.error||port.error)throw cDone.error||port.error;publicClosedCount=Number(cDone.data)||0;if(!isStaff)portfolio=port.data||[];connectionError='';renderPublic()
}catch(e){connectionError='Unable to read live clinic data: '+(e.message||'Unknown error');$('#queueFootnote').textContent=connectionError;$('#queueCount').textContent='Unavailable';console.error(e)}}
// override queue stats for LIVE with a safe aggregate count, never exposing customer records
const rawRenderQueue=renderQueue;renderQueue=function(){if(!LIVE){rawRenderQueue();return}const n=Number(window.__publicQueueCount||0);const held=cases;cases=Array.from({length:n},(_,i)=>({id:i,closed_at:null}));rawRenderQueue();cases=held};
function caseCard(c,kind){return `<div class="case-row"><div><span class="case-id">${esc(c.ref)}</span><h4>${esc(c.card_name)} ${c.priority_service?'<span class="tag" style="background:#e7d5b7;color:#4c3b23">PRIORITY</span>':''} <span class="muted" style="font-weight:400">· ${esc(c.set_name||'Set not recorded')}</span></h4><p>${kind==='admin'?esc(c.owner_email)+' · ':''}${esc(STAGES[Math.max(0,Number(c.stage)-1)]||'Status pending')} </p></div><div class="right"><span class="tag">${c.closed_at?'Closed':`Stage ${Number(c.stage)}/${STAGES.length}`}</span><div style="margin-top:9px"><button class="btn ghost small" data-open-case="${esc(c.id)}">View Case ›</button></div></div></div>`}
let portalTab='overview',caseFilter='open',caseEmail='';
const ICONS={overview:'M3 10.5 12 3l9 7.5V21h-6v-6H9v6H3z',cards:'M4 5h11v15H4zM8 2h12v15',actions:'M5 4h14v16H5zM9 9h6M9 13h6M9 17h3',help:'M12 21a9 9 0 1 0 0-18 9 9 0 0 0 0 18zM9.5 9a2.5 2.5 0 1 1 3.5 2.3c-.6.3-1 .9-1 1.6M12 17h.01',intake:'M12 5v14M5 12h14',clients:'M16 19v-1a4 4 0 0 0-8 0v1M12 11a3 3 0 1 0 0-6 3 3 0 0 0 0 6zM20 19v-1a3 3 0 0 0-2-2.8M4 19v-1a3 3 0 0 1 2-2.8',pricing:'M12 3v18M17 7H9.5a2.5 2.5 0 0 0 0 5h5a2.5 2.5 0 0 1 0 5H7',capacity:'M4 20V10M10 20V4M16 20v-7M22 20H2',portfolio:'M4 5h16v14H4zM4 15l5-5 4 4 3-3 4 4',out:'M15 4h4v16h-4M10 8l-4 4 4 4M6 12h10'};
const ico=n=>`<svg viewBox="0 0 24 24" width="18" height="18" aria-hidden="true"><path d="${ICONS[n]}" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round"/></svg>`;
function navItem(attr,key,label,active,badge){return `<button class="db-nav ${active?'active':''}" ${attr}="${key}">${ico(key)}<span>${label}</span>${badge?`<b class="db-badge">${badge}</b>`:''}</button>`}
function shell(side,main,who){const ini=esc(String(who||'?').trim().charAt(0).toUpperCase());return `<div class="db"><aside class="db-side"><a class="db-brand" href="#home" data-view="public"><img src="assets/logo.png" alt="Cardboard Clinic"></a>${side}<div class="db-who"><span class="db-avatar">${ini}</span><div><small>Signed in</small><span>${esc(who)}</span></div></div><div class="db-foot"><a class="db-nav" href="#home" data-view="public">${ico('overview')}<span>Back to website</span></a><button class="db-nav db-out" data-signout>${ico('out')}<span>Sign out</span></button></div></aside><main class="db-main">${main}</main></div>`}
function clientNeeds(c){if(c.closed_at)return null;if(!caseConsent(c))return 'Sign the consent form';return null}
function stageChip(c){return c.closed_at?'<span class="db-chip done">Returned</span>':`<span class="db-chip">${esc(STAGES[Number(c.stage)-1]||'')}</span>`}
function renderPortal(){if(LIVE&&user&&isStaff&&authMode!=='newpass'){location.hash='#admin';return}const root=$('#portalContent');if(authMode==='newpass'||!(user||demoActor)){root.innerHTML=loginMarkup('portal');return}
const mine=cases.filter(c=>String(c.owner_email).toLowerCase()===realEmail());const todo=mine.filter(clientNeeds);const open=mine.filter(c=>!c.closed_at);
const side=`<nav class="db-navs">${navItem('data-portal-tab','overview','Overview',portalTab==='overview')}${navItem('data-portal-tab','cards','My cards',portalTab==='cards',mine.length||'')}${navItem('data-portal-tab','actions','To do',portalTab==='actions',todo.length?todo.length:'')}${navItem('data-portal-tab','help','Help',portalTab==='help')}</nav>`;
let main='';
if(portalTab==='overview'){const recent=updates.filter(u=>mine.some(c=>c.id===u.case_id)).sort((a,b)=>new Date(b.created_at)-new Date(a.created_at)).slice(0,5);
main=`<header class="db-head"><span class="db-eyebrow">Overview</span><h1>Welcome back</h1><p>Here's where your cards are and anything we need from you.</p></header>
<div class="db-kpis"><div><strong>${mine.length}</strong><span>Cards with us</span></div><div><strong>${open.length}</strong><span>In progress</span></div><div class="${todo.length?'warn':''}"><strong>${todo.length}</strong><span>Need your action</span></div></div>
<section class="db-panel"><h3>Needs your action</h3>${todo.length?todo.map(c=>`<button class="db-row" data-goto-case="${esc(c.id)}"><span><b>${esc(c.card_name)}</b><small>${esc(c.ref)}</small></span><span class="db-chip warn">${clientNeeds(c)}</span><i>›</i></button>`).join(''):'<p class="db-empty">Nothing needed from you right now.</p>'}</section>
<section class="db-panel"><h3>Your cards</h3>${mine.length?mine.map(c=>`<button class="db-row" data-goto-case="${esc(c.id)}"><span><b>${esc(c.card_name)}</b><small>${esc(c.ref)}</small></span>${stageChip(c)}<i>›</i></button>`).join(''):`<p class="db-empty">No cards linked to <strong>${esc(realEmail())}</strong> yet. Once the clinic registers your card under this email, it appears here.</p>`}</section>
<section class="db-panel"><h3>Latest updates</h3>${recent.length?recent.map(u=>{const c=mine.find(x=>x.id===u.case_id);return `<div class="db-feed"><small>${date(u.created_at)}</small><b>${esc(c?.card_name||'')}</b><span>${esc(u.message||STAGES[Number(u.stage)-1]||'Updated')}</span></div>`}).join(''):'<p class="db-empty">Updates from the clinic will show here.</p>'}</section>`}
if(portalTab==='cards'){main=`<header class="db-head"><span class="db-eyebrow">My cards</span><h1>Your card records</h1><p>Pick a card to see its progress, photos and consent form.</p></header><div class="db-split"><section class="db-panel db-list">${mine.length?mine.map(c=>`<button class="db-row ${c.id===activeCaseId?'active':''}" data-goto-case="${esc(c.id)}"><span><b>${esc(c.card_name)}</b><small>${esc(c.ref)}</small></span>${stageChip(c)}</button>`).join(''):'<p class="db-empty">No cards yet.</p>'}</section><section class="db-panel" id="portalDetails"><p class="db-empty">Select a card on the left.</p></section></div>`}
if(portalTab==='actions'){main=`<header class="db-head"><span class="db-eyebrow">To do</span><h1>What we need from you</h1><p>Each card needs a signed consent form before we can start work on it.</p></header><section class="db-panel">${todo.length?todo.map(c=>`<button class="db-row" data-goto-case="${esc(c.id)}"><span><b>${esc(c.card_name)}</b><small>${esc(c.ref)}</small></span><span class="db-chip warn">${clientNeeds(c)}</span><i>›</i></button>`).join(''):'<p class="db-empty">You\'re all caught up.</p>'}</section>`}
if(portalTab==='help'){main=`<header class="db-head"><span class="db-eyebrow">Help</span><h1>Questions about your card?</h1><p>Message us any time. We usually reply the same day.</p></header><section class="db-panel db-help"><a class="db-btn" href="https://wa.me/6598221113" target="_blank" rel="noopener">WhatsApp us · 9822 1113</a><a class="db-link" href="#faq" data-view="public">Read common questions</a><a class="db-link" href="#portal" data-authmode="reset">Change my password</a></section>`}
root.innerHTML=shell(side,main,realEmail());
if(portalTab==='cards'&&activeCaseId&&mine.some(x=>x.id===activeCaseId))openCase(activeCaseId,'portal')}

function stageMarkup(c){const n=Number(c.stage)||1;return `<div class="stage-track" aria-label="Stage ${n} of ${STAGES.length}">${STAGES.map((_,i)=>`<span title="${esc(STAGES[i])}" class="${i+1<n?'done':i+1===n?'current':''}"></span>`).join('')}</div><div class="stage-labels"><span>01 / Registered</span><span>${String(n).padStart(2,'0')} / ${esc(STAGES[n-1]||'Unknown')}</span><span>${STAGES.length} / Ready</span></div>`}

const CONSENT_VERSION='CC-CONSENT-2026-11-v1';
const CONSENT_POINTS=[
 'I confirm that I am the lawful owner of this card or am authorised to request treatment on the owner’s behalf.',
 'I have reviewed the card identification, documented condition, proposed treatments and any priority-service charge for this particular card.',
 'I understand that cleaning, handling, slab extraction and physical restoration carry risks including new marks, colour or finish changes, warping, tears, delamination or permanent damage.',
 'I understand that restoration cannot guarantee invisibility, original factory condition, improved condition, resale value or any particular grading outcome; grading companies may consider a treated card altered.',
 'I authorise only the treatments listed for this card at the price agreed with the clinic. Material changes to treatment scope, price or identified risks require my fresh authorisation before additional work.',
 'I understand that market value may increase or decrease independently of treatment, and Cardboard Clinic does not guarantee or insure future market value unless separately agreed in writing.',
 'I acknowledge that the clinic may decline or stop unsafe treatment, and that any liability limitations apply only to the extent permitted by Singapore law; nothing waives rights that cannot lawfully be excluded.'
];
function scopeSnapshot(c){return JSON.stringify({quote_amount:c.quote_amount==null?null:Number(c.quote_amount),treatment_codes:[...(c.treatment_codes||[])].sort(),priority_service:!!c.priority_service,quote_notes:String(c.quote_notes||''),market_value:Number(c.market_value||0)});}
function caseConsent(c){return consents.filter(a=>a.case_id===c.id).sort((a,b)=>new Date(b.created_at)-new Date(a.created_at))[0]||null}
function consentReady(c){const a=caseConsent(c);return !!(a&&a.admin_verified_at&&a.agreement_version===CONSENT_VERSION)}
function consentMarkup(c,scope){const a=caseConsent(c),ready=consentReady(c);const canSign=scope==='portal'&&!a&&!c.closed_at;
return `<div class="consent-panel" id="consentPanel"><div class="panel-title"><div><span class="eyebrow">Mandatory • One Agreement Per Card</span><h3 style="margin:6px 0">Consent &amp; Authorisation</h3></div><span class="tag ${ready?'care':'risk'}">${ready?'Verified':a?'Awaiting Staff Verification':'Signature Required'}</span></div>
<p class="statusline">Agreement ${esc(CONSENT_VERSION)} · Card ${esc(c.ref)} · ${esc(c.card_name)}. This agreement applies to this card and the treatments listed in this card record.</p>
${a?`<div class="note"><b>Signed by ${esc(a.signer_name)}</b> on ${esc(new Date(a.created_at).toLocaleString('en-SG'))}.<div>Marketing images: ${a.marketing_consent?'Opted in':'Not authorised'}</div><div>${ready?'Clinic verification completed on '+esc(new Date(a.admin_verified_at).toLocaleString('en-SG')):'Awaiting clinic verification — treatment must not begin.'}</div><button class="btn ghost small" type="button" data-print-consent="${esc(c.id)}" style="margin-top:10px">Print / Save Signed Agreement</button></div>`:''}

${canSign?`<form id="consentForm" data-id="${esc(c.id)}"><div class="consent-overview"><b>Authorised card:</b> ${esc(c.card_name)} · ${esc(c.set_name||'')} · ${esc(c.card_number||'')}<div><b>Scope:</b> ${(c.treatment_codes||[]).map(t=>esc(treatment(t).label)).join(', ')||'No treatments selected'}</div>${c.priority_service?'<div><b>Queue:</b> Priority service (+S$75)</div>':''}${c.quote_notes?'<div><b>Conditions:</b> '+esc(c.quote_notes)+'</div>':''}</div><p style="margin:15px 0 8px"><strong>Read and confirm each acknowledgement</strong></p>${CONSENT_POINTS.map((v,i)=>`<label class="consent-check"><input type="checkbox" name="ack${i}" required> <span>${i+1}. ${esc(v)}</span></label>`).join('')}<div class="divider"></div><label class="consent-check"><input type="checkbox" name="marketing"> <span><strong>Optional photo permission:</strong> I separately authorise Cardboard Clinic to publish anonymised before/after images of this card for portfolio, website or marketing use. Declining does not affect service.</span></label><div class="form-grid" style="margin-top:18px"><label class="field"><span>Full legal name / electronic signature *</span><input name="signer_name" required minlength="2" placeholder="Type your full name"></label><label class="field"><span>Relationship to card</span><select name="capacity"><option value="Owner">Owner</option><option value="Authorised representative">Authorised representative</option></select></label></div><label class="consent-check" style="margin-top:14px"><input type="checkbox" name="signature_confirm" required> <span>I intend my typed name and submission to constitute my electronic signature and consent for this specific card.</span></label><div class="actions"><button class="btn gold" type="submit">Sign &amp; Submit Authorisation ›</button><button class="btn ghost small" type="button" data-decision="decline" data-case="${esc(c.id)}">Decline Quotation</button></div><div id="consentMsg"></div></form>`:''}
${scope==='admin'?(a?`<div class="note"><b>Recorded scope:</b> ${esc(a.scope_snapshot)}<div>Consent version: ${esc(a.agreement_version)} · Recorded signer: ${esc(a.signer_name)} · Optional photo permission: ${a.marketing_consent?'Yes':'No'}</div></div>${!ready?`<button class="btn gold small" type="button" data-verify-consent="${esc(c.id)}">Verify Signed Consent</button>`:''}`:'<div class="note">No valid signed authorisation for the current treatment quotation. Do not begin treatment.</div>'):''}
<p class="statusline" style="margin-top:15px">Consent is specific to each card. New approval is required after material changes. The clinic’s terms do not exclude mandatory consumer rights.</p></div>`}
function printConsent(c){const a=caseConsent(c);if(!a)return;const text=[`CARDBOARD CLINIC — CONSENT & AUTHORISATION`,`Agreement: ${a.agreement_version}`,`Case: ${c.ref}`,`Card: ${c.card_name} / ${c.set_name||''} / ${c.card_number||''}`,`Treatments: ${(c.treatment_codes||[]).map(x=>treatment(x).label).join(', ')}`,`Priority service: ${c.priority_service?'Yes':'No'}`,`Signed: ${a.signer_name}`,`Capacity: ${a.signer_capacity||'Owner'}`,`Time: ${new Date(a.created_at).toLocaleString('en-SG')}`,`Marketing consent: ${a.marketing_consent?'Yes':'No'}`,`Admin verified: ${a.admin_verified_at||'Not yet verified'}`,'',...CONSENT_POINTS.map((x,i)=>`${i+1}. [AGREED] ${x}`)].join('\n\n');const w=window.open('','_blank');if(!w){alert('Allow popups to print this agreement.');return}w.document.write('<!doctype html><html><head><title>Consent '+esc(c.ref)+'</title><style>body{font:14px/1.65 Arial;max-width:780px;margin:40px auto;padding:20px}pre{white-space:pre-wrap;font:inherit}</style></head><body><pre>'+esc(text)+'</pre></body></html>');w.document.close();w.focus();w.print()}
async function signConsent(f){const c=cases.find(x=>x.id===f.dataset.id);if(!c||c.owner_email.toLowerCase()!==realEmail())throw Error('This card is not linked to your account.');if(caseConsent(c))throw Error('This card already has a signed form.');const fd=new FormData(f);if(!CONSENT_POINTS.every((_,i)=>fd.has('ack'+i))||!fd.has('signature_confirm'))throw Error('Please confirm every mandatory acknowledgement and the signature.');const name=String(fd.get('signer_name')||'').trim();if(name.length<2)throw Error('Enter your full name.');const data={case_id:c.id,agreement_version:CONSENT_VERSION,scope_snapshot:scopeSnapshot(c),signer_name:name,signer_capacity:String(fd.get('capacity')||'Owner'),marketing_consent:fd.has('marketing'),acknowledgements:CONSENT_POINTS.map((_,i)=>i+1)};
if(LIVE){const {data:row,error}=await db.from('case_consents').insert(data).select().single();if(error)throw error;consents.unshift(row)}else consents.unshift({...data,id:uid(),created_at:new Date().toISOString(),admin_verified_at:null});persist();return c}
async function verifyConsent(id){const c=cases.find(x=>x.id===id),a=c&&caseConsent(c);if(!a||a.admin_verified_at)throw Error('No unverified form for this card.');if(!confirm(`Verify the signed agreement for ${c.ref}? This confirms the signed card, scope, pricing and required acknowledgements.`))return;if(LIVE){const {data,error}=await db.from('case_consents').update({admin_verified_at:new Date().toISOString(),verified_by:user.id}).eq('id',a.id).is('admin_verified_at',null).select().single();if(error)throw error;Object.assign(a,data)}else a.admin_verified_at=new Date().toISOString();persist();await openCase(id,'admin')}

function latestDecision(c){return decisions.filter(d=>d.case_id===c.id).sort((a,b)=>new Date(b.created_at)-new Date(a.created_at))[0]}
function timelineMarkup(c){const u=updates.filter(x=>x.case_id===c.id).sort((a,b)=>new Date(b.created_at)-new Date(a.created_at));return u.length?`<div class="timeline">${u.map(x=>`<div class="timeline-item"><b>${esc(STAGES[Number(x.stage)-1]||'Progress update')}</b><small>${date(x.created_at)}</small><div>${esc(x.message||'Status updated')}</div></div>`).join('')}</div>`:'<div class="empty">Treatment updates will be added by our team.</div>'}
function quoteMarkup(c,scope){const d=latestDecision(c),canDecide=scope==='portal'&&c.quote_status==='issued'&&c.quote_amount!=null&&!d;return `<div class="case-detail"><span class="eyebrow">Proposed Treatment & Quotation</span><div class="case-info" style="margin-top:12px"><div><span>Current card value</span><b>${money(c.market_value||0)}</b></div><div><span>Quote</span><b>${c.quote_amount!=null?money(c.quote_amount):'Pending diagnosis'}</b></div><div><span>Queue</span><b>${c.priority_service?'Priority requested / staff-assigned':'Standard'}</b></div><div><span>Quote status</span><b>${d?('Client '+d.decision):esc(c.quote_status||'Pending')}</b></div></div><div style="margin-top:16px"><small>Assigned treatments</small><div>${(c.treatment_codes||[]).map(x=>`<span class="tag" style="margin-right:6px;margin-top:7px">${esc(treatment(x).label)}</span>`).join('')||'None assigned'}</div></div>${c.quote_notes?`<p style="font-size:12px;margin-top:13px">${esc(c.quote_notes)}</p>`:''}${canDecide?`<div class="note" style="margin-top:15px"><strong>Consent:</strong> I understand this is an optional treatment, that physical results are uncertain, and grading companies may reject restored or altered cards. I approve the quoted scope and price only. </div><div class="actions"><span class="statusline">To approve, complete the detailed per-card Consent &amp; Authorisation form below.</span><button class="btn ghost small" data-decision="decline" data-case="${esc(c.id)}">Decline Quote</button></div>`:''}${d?`<p style="font-size:12px;margin-top:12px">Client decision logged ${date(d.created_at)}. Staff confirmation may follow.</p>`:''}</div>`}
async function photoMarkup(c,scope){const casePhotos=photos.filter(x=>x.case_id===c.id);if(!casePhotos.length)return '<div class="empty">Photos will appear here when uploaded by the clinic.</div>';const tiles=await Promise.all(casePhotos.map(async p=>{let url='';if(LIVE){const x=await db.storage.from('case-media').createSignedUrl(p.storage_path,600);url=x.data?.signedUrl||''}else url=p.preview_url||'';return url?`<a href="${esc(url)}" target="_blank" rel="noopener"><img loading="lazy" src="${esc(url)}" alt="${esc(p.phase||'Card photo')}"><small style="display:block;padding:7px">${esc(p.phase||'Assessment')} · ${date(p.created_at)}</small></a>`:''}));return `<div class="photo-grid">${tiles.join('')}</div>`}
async function openCase(id,scope){const c=cases.find(x=>x.id===id);if(!c)return;activeCaseId=id;const dest=$(scope==='portal'?'#portalDetails':'#adminCaseDetails');if(!dest)return;dest.innerHTML=`<div class="panel-title"><div><span class="case-id">${esc(c.ref)}</span><h3 style="margin:5px 0">${esc(c.card_name)}</h3></div><span class="tag">${esc(STAGES[Number(c.stage)-1])}</span></div><p style="font-size:12px">${esc(c.set_name||'')}${c.card_number?' · #'+esc(c.card_number):''}${c.card_year?' · '+esc(c.card_year):''}</p><h4 style="margin-bottom:5px">Recovery Tracking</h4>${stageMarkup(c)}${consentMarkup(c,scope)}<h4 style="margin:24px 0 5px">Treatment Timeline</h4>${timelineMarkup(c)}<h4 style="margin:18px 0 6px">Assessment & Final Photos</h4><div id="photoSlot">Loading photos…</div>${scope==='admin'?adminCaseControls(c):''}`;dest.querySelector('#photoSlot').innerHTML=await photoMarkup(c,scope)}
function adminCaseControls(c){return `<div class="divider"></div><h4>Update Card record</h4><form id="updateCase" data-id="${esc(c.id)}"><div class="form-grid"><label class="field"><span>Stage</span><select name="stage">${STAGES.map((s,i)=>`<option value="${i+1}" ${Number(c.stage)===i+1?'selected':''}>${i+1}. ${esc(s)}</option>`).join('')}</select></label><label class="field"><span>Verified raw-card value (S$)</span><input name="market_value" type="number" min="0" step=".01" value="${Number(c.market_value)||0}"></label><label class="check-label span2" style="display:flex;gap:10px;align-items:center"><input name="priority_service" type="checkbox" ${c.priority_service?'checked':''}> Priority Queue enabled (+ S$75 / card)</label><label class="field span2"><span>Progress note (added to timeline)</span><textarea name="message" placeholder="e.g. Surface inspection complete, awaiting approval"></textarea></label></div><div class="actions"><button class="btn gold small" type="submit">Save Case Update</button><button class="btn ghost small" type="button" data-close-case="${esc(c.id)}">${c.closed_at?'Reopen Case':'Mark Returned / Close Case'}</button></div><div id="updateMsg"></div></form><div class="divider"></div><h4>Upload Assessment / After Photos</h4><form id="uploadPhotos" data-id="${esc(c.id)}"><div class="form-grid"><label class="field"><span>Photo stage</span><select name="phase"><option value="before">Before / Intake</option><option value="during">During Treatment</option><option value="after">After / Final</option></select></label><label class="field"><span>Card photographs</span><input name="images" type="file" accept="image/jpeg,image/png,image/webp" multiple required></label></div><p class="statusline">Images remain in a private storage bucket; signed links expire. Avoid uploading confidential photos in demo mode.</p><button class="btn ghost small" style="margin-top:12px" type="submit">Upload Photos</button><div id="uploadMsg"></div></form>`}
function staffQueues(){const live=cases.filter(c=>!c.closed_at);const q=(t,f)=>({t,list:live.filter(f)});return [
 q('Waiting for client to sign',c=>!caseConsent(c)),
 q('Signed form to verify',c=>{const a=caseConsent(c);return a&&!a.admin_verified_at}),
 q('Awaiting payment',c=>consentReady(c)&&Number(c.stage)<7),
 q('In treatment',c=>Number(c.stage)>=7&&Number(c.stage)<=11),
 q('Ready to return',c=>Number(c.stage)>=12)]}
function renderAdmin(){const root=$('#adminContent');if(!(isStaff||demoActor?.staff)){root.innerHTML=loginMarkup('admin');return}
const qs=staffQueues();const urgent=qs[1].list.length+qs[2].list.length;
const side=`<span class="db-group">Daily work</span><nav class="db-navs">${navItem('data-admin-tab','overview','Overview',adminTab==='overview',urgent||'')}${navItem('data-admin-tab','cards','Cards',adminTab==='cases'||adminTab==='cards',cases.filter(c=>!c.closed_at).length||'')}${navItem('data-admin-tab','intake','New intake',adminTab==='intake')}${navItem('data-admin-tab','clients','Clients',adminTab==='clients')}</nav><span class="db-group">Website</span><nav class="db-navs">${navItem('data-admin-tab','pricing','Pricing',adminTab==='pricing')}${navItem('data-admin-tab','capacity','Queue & reviews',adminTab==='capacity')}${navItem('data-admin-tab','portfolio','Portfolio',adminTab==='portfolio')}</nav>`;
root.innerHTML=shell(side,'<div id="adminWorkspace"></div>',realEmail()||'Staff');renderAdminTab()}

function renderAdminTab(){const x=$('#adminWorkspace');if(!x)return;
if(adminTab==='cases')adminTab='cards';
if(adminTab==='overview'){const qs=staffQueues();x.innerHTML=`<header class="db-head"><span class="db-eyebrow">Overview</span><h1>Today at the clinic</h1><p>Everything waiting on you or a client, in workflow order.</p></header>
<div class="db-kpis"><div><strong>${cases.filter(c=>!c.closed_at).length}</strong><span>Active cards</span></div><div><strong>${qs[0].list.length}</strong><span>Waiting on clients</span></div><div class="${qs[1].list.length+qs[2].list.length?'warn':''}"><strong>${qs[1].list.length+qs[2].list.length}</strong><span>Waiting on you</span></div><div><strong>${cases.filter(c=>!!c.closed_at).length}</strong><span>Returned</span></div></div>
<div class="db-board">${qs.map(g=>`<section class="db-panel"><h3>${g.t}<b>${g.list.length}</b></h3>${g.list.length?g.list.map(c=>`<button class="db-row" data-goto-case="${esc(c.id)}"><span><b>${esc(c.card_name)}</b><small>${esc(c.client_name||c.owner_email)} · ${esc(c.ref)}</small></span><i>›</i></button>`).join(''):'<p class="db-empty">None</p>'}</section>`).join('')}</div>`;return}
if(adminTab==='clients'){const by={};cases.forEach(c=>{const k=String(c.owner_email).toLowerCase();(by[k]=by[k]||{name:c.client_name,email:k,list:[]}).list.push(c)});const rows=Object.values(by).sort((a,b)=>b.list.length-a.list.length);
x.innerHTML=`<header class="db-head"><span class="db-eyebrow">Clients</span><h1>Everyone you've worked with</h1><p>Grouped by the email each card is registered under.</p></header><section class="db-panel">${rows.length?`<div class="db-table"><div class="db-tr db-th"><span>Client</span><span>Cards</span><span>In progress</span><span></span></div>${rows.map(r=>`<button class="db-tr" data-client="${esc(r.email)}"><span><b>${esc(r.name||'—')}</b><small>${esc(r.email)}</small></span><span>${r.list.length}</span><span>${r.list.filter(c=>!c.closed_at).length}</span><i>›</i></button>`).join('')}</div>`:'<p class="db-empty">Clients appear here once you register their first card.</p>'}</section>`;return}
if(adminTab==='cards'){const filt=c=>(caseFilter==='open'?!c.closed_at:caseFilter==='closed'?!!c.closed_at:true)&&(!caseEmail||String(c.owner_email).toLowerCase()===caseEmail);const list=cases.filter(filt);
x.innerHTML=`<header class="db-head"><span class="db-eyebrow">Cards</span><h1>Card records</h1><p>Open a card to verify its form, move its stage, and add notes and photos.</p></header>
<div class="db-filters">${[['open','In progress'],['all','All'],['closed','Returned']].map(([k,l])=>`<button class="db-pill ${caseFilter===k?'active':''}" data-case-filter="${k}">${l}</button>`).join('')}${caseEmail?`<button class="db-pill active" data-client="">${esc(caseEmail)} ✕</button>`:''}<input id="caseSearch" class="db-search" placeholder="Search reference, card or email"></div>
<div class="db-split"><section class="db-panel db-list" id="adminCaseList">${list.length?list.map(c=>`<button class="db-row ${c.id===activeCaseId?'active':''}" data-goto-case="${esc(c.id)}"><span><b>${esc(c.card_name)}</b><small>${esc(c.client_name||c.owner_email)} · ${esc(c.ref)}</small></span>${stageChip(c)}</button>`).join(''):'<p class="db-empty">No cards here yet.</p>'}</section><section class="db-panel" id="adminCaseDetails"><p class="db-empty">Select a card on the left.</p></section></div>`;
if(activeCaseId&&cases.some(c=>c.id===activeCaseId))openCase(activeCaseId,'admin');return}
if(false){x.innerHTML=`<div class="kpis"><div class="kpi"><strong>${cases.filter(c=>!c.closed_at).length}</strong><span>Active Cards</span></div><div class="kpi"><strong>${cases.filter(c=>c.quote_status==='issued').length}</strong><span>Quotes Issued</span></div><div class="kpi"><strong>${cases.filter(c=>!!c.closed_at).length}</strong><span>Closed Cases</span></div></div><div class="two-col"><div class="panel"><h3>All card records</h3><label class="field"><span>Find by reference, card or email</span><input id="caseSearch" placeholder="Search cases…"></label><div class="case-list" id="adminCaseList" style="margin-top:14px">${cases.length?cases.map(c=>caseCard(c,'admin')).join(''):'<div class="empty">No cases created yet.</div>'}</div></div><div class="panel" id="adminCaseDetails"><h3>Card case</h3><div class="empty">Select a card record to view or update its stage, quote and images.</div></div></div>`;if(activeCaseId&&cases.some(c=>c.id===activeCaseId))openCase(activeCaseId,'admin');return}
if(adminTab==='intake'){x.innerHTML=`<div class="panel"><span class="eyebrow">Staff-Controlled Registration</span><h3 style="margin:9px 0">Create a card record</h3><p style="font-size:13px">Only authorised clinic staff can register new cards. The owner sees the case in their private portal after an email/password account is provisioned for the same email.</p><form id="intakeForm"><div class="form-grid"><label class="field"><span>Client name *</span><input name="client_name" required></label><label class="field"><span>Client email * (portal link)</span><input type="email" name="owner_email" required></label><label class="field"><span>Card name *</span><input name="card_name" required placeholder="e.g. Charizard"></label><label class="field"><span>Set / series</span><input name="set_name" placeholder="e.g. Base Set"></label><label class="field"><span>Collector / set number</span><input name="card_number"></label><label class="field"><span>Card year</span><input name="card_year"></label><label class="field"><span>Client-declared value (S$)</span><input name="declared_value" type="number" min="0" step=".01"></label><label class="field"><span>Verified current ungraded value (S$) *</span><input id="intakeValue" name="market_value" type="number" value="0" min="0" step=".01" required></label></div><div class="divider"></div><strong style="font-size:13px">Affected Areas / Proposed Treatments</strong><div class="checkbox-grid">${prices.filter(p=>p.active!==false&&p.code!=='assessment'&&p.code!=='report').map(p=>`<label class="check-label"><input type="checkbox" name="treatments" value="${esc(p.code)}">${esc(p.label)}</label>`).join('')}</div><label class="check-label" style="margin:14px 0;display:flex;gap:10px;align-items:center"><input type="checkbox" name="priority_service"> Request Priority Queue (+ S$75 / card; subject to staff acceptance)</label><div class="form-grid"><label class="field"><span>Quote amount (S$) — review before issuing</span><input id="intakeQuote" name="quote_amount" type="number" min="0" step=".01"></label><label class="field"><span>Initial workflow stage</span><select name="stage">${STAGES.map((s,i)=>`<option value="${i+1}" ${i===0?'selected':''}>${i+1}. ${esc(s)}</option>`).join('')}</select></label><label class="field span2"><span>Pre-assessment findings</span><textarea name="notes" placeholder="Front/back defects, location, severity, grading risks..."></textarea></label><label class="field span2"><span>Quotation conditions</span><textarea name="quote_notes" placeholder="Scope of work, damage limitations, informed consent..."></textarea></label><label class="field span2"><span>Pre-assessment photos (front, back, close-ups)</span><input type="file" name="images" accept="image/jpeg,image/png,image/webp" multiple></label></div><div class="actions"><button type="button" class="btn ghost small" id="suggestQuote">Calculate Indicative Quote</button><button type="submit" class="btn gold">Create Card Record ›</button></div><div id="intakeMsg"></div></form></div>`;return}
if(adminTab==='pricing'){x.innerHTML=`<div class="panel"><span class="eyebrow">Staff-Managed Public Rates</span><h3 style="margin:8px 0">Published Treatments & Base Rates</h3><p style="font-size:13px">Changes here update the public price list and estimator. Value-based multipliers apply to structural treatments only. Editing records does not automatically alter previously issued customer quotations.</p><div id="adminPriceRows">${prices.map(p=>`<div class="price-edit-row"><label>${esc(p.label)}<small style="display:block;color:#878d84">${p.category==='restore'?'Structural / value-scaled':'Flat-rate'}</small></label><input id="price_${esc(p.code)}" type="number" min="0" step=".01" value="${Number(p.base)}" aria-label="Base price for ${esc(p.label)}"><button data-save-price="${esc(p.code)}">Save</button></div>`).join('')}</div><div class="divider"></div><h3>Market Value Bands</h3><p style="font-size:12px">High-value cards at or above S$5,000 are custom-quoted. These multipliers are suggested launch defaults and can be reviewed later.</p>${tiers.map(t=>`<div class="price-edit-row"><label>${esc(t.label)}</label><div>${t.multiplier==null?'Custom quote':Number(t.multiplier).toFixed(2)+'×'}</div><span class="tag">${t.multiplier==null?'Review':'Active'}</span></div>`).join('')}<div id="pricingMsg"></div></div>`;return}
if(adminTab==='portfolio'){x.innerHTML=portfolioAdmin();return}
 if(adminTab==='capacity'){x.innerHTML=`<div class="two-col"><div class="panel"><span class="eyebrow">Queue Settings</span><h3 style="margin:9px 0">Active Workload</h3><p style="font-size:13px">The public queue count is derived from open card cases; capacity and weekly processing pace can be changed here.</p><form id="settingsForm"><label class="field"><span>Maximum active cards</span><input name="capacity" type="number" value="${Number(settings.capacity)}" min="1" max="1000" required></label><label class="field"><span>Estimated cards handled weekly</span><input name="weekly_rate" type="number" value="${Number(settings.weekly_rate)}" min="1" max="200" required></label><button class="btn gold small" style="margin-top:18px">Update Public Capacity</button><div id="settingsMsg"></div></form></div><div class="panel"><span class="eyebrow">Curated Testimonials</span><h3 style="margin:9px 0">Publish a Past Review</h3><p style="font-size:13px">Only post an authentic review already received from a real client, with their permission to publish.</p><form id="reviewForm"><label class="field"><span>Public display name *</span><input name="display_name" required></label><label class="field"><span>Review source *</span><input name="review_source" required placeholder="Google / email / existing client"></label><label class="field"><span>Review text *</span><textarea name="review_text" required></textarea></label><label style="font-size:12px;display:flex;gap:9px;margin-top:11px"><input name="permission" type="checkbox" required> I confirm this review is genuine and permission was obtained.</label><button class="btn ghost small" style="margin-top:17px" type="submit">Publish Existing Review</button><div id="reviewMsg"></div></form></div></div><div class="panel top-gap"><h3>Published Reviews</h3>${reviews.filter(r=>r.is_published).map(r=>`<div class="case-row"><div><b>${esc(r.display_name)}</b><p>${esc(r.review_text)}</p></div><button class="btn ghost small" data-unpublish="${esc(r.id)}">Unpublish</button></div>`).join('')||'<div class="empty">No approved past reviews published yet.</div>'}</div>`;return}}
async function makeCase(form){const fd=new FormData(form);const cs=[...form.querySelectorAll('[name=treatments]:checked')].map(x=>x.value);const obj={ref:'CC-'+new Date().toISOString().slice(2,10).replaceAll('-','')+'-'+Math.floor(Math.random()*9000+1000),client_name:String(fd.get('client_name')).trim(),owner_email:String(fd.get('owner_email')).trim().toLowerCase(),card_name:String(fd.get('card_name')).trim(),set_name:String(fd.get('set_name')||''),card_number:String(fd.get('card_number')||''),card_year:String(fd.get('card_year')||''),declared_value:Number(fd.get('declared_value')||0),market_value:Number(fd.get('market_value')||0),treatment_codes:cs,priority_service:fd.has('priority_service'),quote_amount:fd.get('quote_amount')?Number(fd.get('quote_amount')):null,quote_status:'pending',stage:Math.min(6,Number(fd.get('stage')||1)),quote_notes:String(fd.get('quote_notes')||''),notes:String(fd.get('notes')||''),closed_at:null};
let created;if(LIVE){const {data,error}=await db.from('cards').insert(obj).select().single();if(error)throw error;created=data;cases.unshift(data)}else{created={id:uid(),...obj,created_at:new Date().toISOString(),updated_at:new Date().toISOString()};cases.unshift(created)}await addUpdate(created.id,created.stage,'Case registered by clinic staff.');const files=[...form.querySelector('[name=images]').files];if(files.length)await uploadPhotoFiles(created.id,'before',files);persist();renderQueue();return created}
async function addUpdate(id,stage,message){const u={case_id:id,stage:Number(stage),message:message||'Status updated'};if(LIVE){const {data,error}=await db.from('case_updates').insert(u).select().single();if(error)throw error;updates.unshift(data)}else{updates.unshift({...u,id:uid(),created_at:new Date().toISOString()});persist()}}
async function uploadPhotoFiles(caseId,phase,files){for(const file of files){if(!/^image\/(jpeg|png|webp)$/.test(file.type))throw Error('Only JPEG, PNG and WebP image formats can be uploaded.');if(file.size>8*1024*1024)throw Error('Maximum photo size is 8 MB per image.');if(LIVE){const ext=file.name.split('.').pop()?.toLowerCase()||'jpg',path=`${caseId}/${uid()}.${ext}`;const {error:upErr}=await db.storage.from('case-media').upload(path,file,{contentType:file.type,upsert:false});if(upErr)throw upErr;const p={case_id:caseId,phase,storage_path:path};const {data,error}=await db.from('case_photos').insert(p).select().single();if(error)throw error;photos.unshift(data)}else{const url=await new Promise((res,rej)=>{const rd=new FileReader();rd.onload=()=>res(rd.result);rd.onerror=()=>rej(Error('Unable to preview image'));rd.readAsDataURL(file)});photos.unshift({id:uid(),case_id:caseId,phase,preview_url:url,created_at:new Date().toISOString()})}}persist()}
async function updateCase(form){const c=cases.find(x=>x.id===form.dataset.id);if(!c)throw Error('Case not found');const fd=new FormData(form);const change={stage:Number(fd.get('stage')),quote_status:fd.get('quote_status')||c.quote_status||'pending',priority_service:fd.has('priority_service'),market_value:fd.has('market_value')?Number(fd.get('market_value')||0):Number(c.market_value||0),quote_amount:fd.has('quote_amount')?(fd.get('quote_amount')?Number(fd.get('quote_amount')):null):c.quote_amount??null,quote_notes:fd.has('quote_notes')?String(fd.get('quote_notes')||''):String(c.quote_notes||'')};if(Number(change.stage)>=7&&!consentReady(c))throw Error('Payment and later stages need a signed and staff-verified consent form for this card.');const message=String(fd.get('message')||'').trim(),stageChange=Number(c.stage)!==change.stage;
if(LIVE){const {data,error}=await db.from('cards').update(change).eq('id',c.id).select().single();if(error)throw error;Object.assign(c,data)}else Object.assign(c,change,{updated_at:new Date().toISOString()});if(message||stageChange)await addUpdate(c.id,c.stage,message||'Stage changed by clinic staff.');persist();return c}
async function makeDecision(id,decision){const c=cases.find(x=>x.id===id);if(!c||String(c.owner_email).toLowerCase()!==realEmail())throw Error('This card is not linked to the signed-in customer.');if(c.quote_status!=='issued')throw Error('The quote is not currently open for approval.');if(latestDecision(c))throw Error('A decision has already been recorded.');const r={case_id:id,decision};if(LIVE){const {data,error}=await db.from('quote_decisions').insert(r).select().single();if(error)throw error;decisions.unshift(data)}else decisions.unshift({...r,id:uid(),created_at:new Date().toISOString()});persist()}
async function loadLive(){const {data:{session}}=await db.auth.getSession();user=session?.user||null;await checkStaff();await refreshPublic();if(user)await refreshCases()}
function bind(){window.addEventListener('hashchange',route);$('#mobileNav').addEventListener('click',()=>{const x=$('#navlinks');x.classList.toggle('open');$('#mobileNav').setAttribute('aria-expanded',String(x.classList.contains('open')))});$('#calcValue').addEventListener('input',calc);$('#calcPriority').addEventListener('change',calc);$('#calcTreatments').addEventListener('change',calc);
document.addEventListener('click',async e=>{const am=e.target.closest('[data-authmode]');if(am){e.preventDefault();authFlipTo(am.dataset.authmode);return}const link=e.target.closest('[data-view]');if(link){$('#navlinks').classList.remove('open')}
const demo=e.target.closest('#portalDemo,#adminDemo');if(demo){const k=demo.id==='portalDemo'?'portal':'admin';demoActor=k==='portal'?{email:'collector@example.com'}:{email:'collector@example.com',staff:true};k==='portal'?renderPortal():renderAdmin();return}
if(e.target.closest('[data-signout]')){await signOut();return}
const tab=e.target.closest('[data-admin-tab]');if(tab){adminTab=tab.dataset.adminTab;activeCaseId=null;renderAdmin();return}
const ptab=e.target.closest('[data-portal-tab]');if(ptab){portalTab=ptab.dataset.portalTab;renderPortal();window.scrollTo({top:0});return}
const cf=e.target.closest('[data-case-filter]');if(cf){caseFilter=cf.dataset.caseFilter;renderAdminTab();return}
const cl=e.target.closest('[data-client]');if(cl){caseEmail=cl.dataset.client;caseFilter='all';adminTab='cards';activeCaseId=null;renderAdmin();return}
const go=e.target.closest('[data-goto-case]');if(go){activeCaseId=go.dataset.gotoCase;if(location.hash==='#portal'){portalTab='cards';renderPortal()}else{adminTab='cards';renderAdmin()}if(innerWidth<900)setTimeout(()=>document.getElementById(location.hash==='#portal'?'portalDetails':'adminCaseDetails')?.scrollIntoView({behavior:'smooth'}),80);return}
const verify=e.target.closest('[data-verify-consent]');if(verify){try{await verifyConsent(verify.dataset.verifyConsent)}catch(err){alert(err.message)}return}
const printBtn=e.target.closest('[data-print-consent]');if(printBtn){const c=cases.find(x=>x.id===printBtn.dataset.printConsent);if(c)printConsent(c);return}
const opened=e.target.closest('[data-open-case]');if(opened){openCase(opened.dataset.openCase,location.hash==='#portal'?'portal':'admin');return}
const quote=e.target.closest('[data-decision]');if(quote){const dec='declined';if(!confirm(`Record your decision: ${dec.toUpperCase()}? This confirms your response to the quoted treatment, not a guaranteed outcome.`))return;quote.disabled=true;try{await makeDecision(quote.dataset.case,dec);renderPortal()}catch(err){alert(err.message)}finally{quote.disabled=false}return}
const price=e.target.closest('[data-save-price]');if(price){const code=price.dataset.savePrice;const t=prices.find(x=>x.code===code),v=Number($(`#price_${code}`).value);if(!t||!Number.isFinite(v)||v<0){setMessage('#pricingMsg','Enter a valid non-negative rate.',true);return}price.disabled=true;try{if(LIVE){const {error}=await db.from('pricing_services').update({base:v}).eq('code',code);if(error)throw error}t.base=v;persist();renderPublic();setMessage('#pricingMsg',t.label+' updated successfully.')}catch(err){setMessage('#pricingMsg',err.message,true)}finally{price.disabled=false}return}
const close=e.target.closest('[data-close-case]');if(close){const c=cases.find(x=>x.id===close.dataset.closeCase);if(!c)return;if(!confirm(c.closed_at?'Reopen this case?':'Confirm the card is returned and the case can be closed?'))return;try{const stamp=c.closed_at?null:new Date().toISOString();if(LIVE){const {error}=await db.from('cards').update({closed_at:stamp}).eq('id',c.id);if(error)throw error}c.closed_at=stamp;persist();if(LIVE)await refreshPublic();renderAdmin();renderQueue();renderRestoredCount()}catch(err){alert(err.message)}return}
const toggleP=e.target.closest('[data-toggle-portfolio]');if(toggleP){const p=portfolio.find(x=>String(x.id)===toggleP.dataset.togglePortfolio);if(!p)return;try{if(LIVE){const {error}=await db.from('restoration_portfolio').update({is_published:!p.is_published}).eq('id',p.id);if(error)throw error}p.is_published=!p.is_published;persist();renderPortfolio();renderAdmin()}catch(err){alert(err.message)}return}
 const unpub=e.target.closest('[data-unpublish]');if(unpub){const r=reviews.find(x=>String(x.id)===unpub.dataset.unpublish);if(!r)return;try{if(LIVE){const {error}=await db.from('client_reviews').update({is_published:false}).eq('id',r.id);if(error)throw error}r.is_published=false;persist();renderAdmin();renderReviews()}catch(err){alert(err.message)}return}
const quoteCalc=e.target.closest('#suggestQuote');if(quoteCalc){const form=$('#intakeForm');const cs=[...form.querySelectorAll('[name=treatments]:checked')].map(x=>x.value),v=Number(form.market_value.value)||0;const base=estimateTreatments(cs,v);const n=base==null?null:base+(form.priority_service.checked?75:0);if(!cs.length){setMessage('#intakeMsg','Select at least one treatment first.',true);return}if(n==null){setMessage('#intakeMsg','High-value specialist case — create a manual quote after assessment.');return}form.quote_amount.value=n;setMessage('#intakeMsg','Indicative total '+money(n)+' including any Priority Queue fee, before multi-treatment adjustments. Check the quote and conditions before issuing.');return}});
document.addEventListener('input',e=>{if(e.target?.id==='caseSearch'){const q=e.target.value.trim().toLowerCase();$('#adminCaseList').innerHTML=cases.filter(c=>[c.ref,c.card_name,c.owner_email,c.client_name].some(x=>String(x).toLowerCase().includes(q))).map(c=>`<button class="db-row" data-goto-case="${esc(c.id)}"><span><b>${esc(c.card_name)}</b><small>${esc(c.client_name||c.owner_email)} · ${esc(c.ref)}</small></span>${stageChip(c)}</button>`).join('')||'<div class="empty">No matching cases found.</div>'}});
document.addEventListener('submit',async e=>{const f=e.target;if(!f.id)return;const known=['portalLogin','adminLogin','intakeForm','updateCase','uploadPhotos','settingsForm','reviewForm','portfolioForm','historicalForm','consentForm','portalSignup','portalReset','portalNewPassword'];if(!known.includes(f.id))return;e.preventDefault();const submit=f.querySelector('[type=submit]');if(submit)submit.disabled=true;
try{if(f.id==='portalSignup'){await portalSignup(f);return}if(f.id==='portalReset'){if(!LIVE){setMessage('#portalLoginMsg','Accounts are opening soon. For an update on your card, WhatsApp us on 9822 1113.',true);return}await portalReset(f);return}if(f.id==='portalNewPassword'){await portalNewPassword(f);return}
if(f.id==='portalLogin'||f.id==='adminLogin'){await signIn(f.id==='portalLogin'?'portal':'admin',f);return}
if(f.id==='intakeForm'){const c=await makeCase(f);if(LIVE)await refreshPublic();setMessage('#intakeMsg','Card '+c.ref+' created. Ensure the client has a provisioned Supabase Auth account at the same email to sign in.');f.reset();renderPublic();return}
if(f.id==='consentForm'){const c=await signConsent(f);await openCase(c.id,'portal');return}
if(f.id==='updateCase'){const c=await updateCase(f);renderAdmin();await openCase(c.id,'admin');setMessage('#updateMsg','Changes saved.');return}
if(f.id==='uploadPhotos'){const fd=new FormData(f);await uploadPhotoFiles(f.dataset.id,String(fd.get('phase')),[...f.images.files]);await openCase(f.dataset.id,'admin');setMessage('#uploadMsg','Images uploaded.');return}
if(f.id==='settingsForm'){const obj={capacity:Math.max(1,Number(f.capacity.value)),weekly_rate:Math.max(1,Number(f.weekly_rate.value))};if(LIVE){const {error}=await db.from('clinic_settings').update(obj).eq('id',1);if(error)throw error}settings={...settings,...obj};persist();renderQueue();setMessage('#settingsMsg','Public queue settings updated.');return}
if(f.id==='historicalForm'){const n=Number(new FormData(f).get('historical_count'));if(!Number.isSafeInteger(n)||n<0)throw Error('Enter a non-negative whole number.');if(LIVE){const {error}=await db.from('clinic_settings').update({historical_completed:n}).eq('id',1);if(error)throw error}historicalCount=n;persist();renderRestoredCount();renderAdmin();setMessage('#historicalMsg','Starting counter saved.');return}
 if(f.id==='portfolioForm'){await publishPortfolio(f);renderAdmin();setMessage('#portfolioMsg','Portfolio case published.');return}
 if(f.id==='reviewForm'){if(!f.permission.checked)throw Error('Permission confirmation is required.');const obj={display_name:String(f.display_name.value).trim(),review_source:String(f.review_source.value).trim(),review_text:String(f.review_text.value).trim(),is_published:true};if(LIVE){const {data,error}=await db.from('client_reviews').insert(obj).select().single();if(error)throw error;reviews.unshift(data)}else reviews.unshift({...obj,id:uid(),created_at:new Date().toISOString()});persist();renderReviews();renderAdmin();setMessage('#reviewMsg','Review published.');return}
}catch(err){const place=f.id==='consentForm'?'#consentMsg':f.id==='intakeForm'?'#intakeMsg':f.id==='settingsForm'?'#settingsMsg':f.id==='historicalForm'?'#historicalMsg':f.id==='portfolioForm'?'#portfolioMsg':f.id==='reviewForm'?'#reviewMsg':f.id==='uploadPhotos'?'#uploadMsg':f.id==='updateCase'?'#updateMsg':['portalLogin','portalSignup','portalReset','portalNewPassword'].includes(f.id)?'#portalLoginMsg':'#adminLoginMsg';setMessage(place,err.message||'Unable to save',true)}finally{if(submit)submit.disabled=false}})
}
async function init(){document.getElementById('year').textContent=new Date().getFullYear();$('#demoBanner').hidden=LIVE;bind();if(LIVE){await loadLive();db.auth.onAuthStateChange((ev,s)=>{setTimeout(async()=>{if(ev==='PASSWORD_RECOVERY'){authMode='newpass';location.hash='#portal';route();renderPortal()}else if(ev==='SIGNED_OUT'){user=null;isStaff=false;cases=[];renderPortal();renderAdmin()}else if(ev==='SIGNED_IN'&&s?.user&&s.user.id!==user?.id){user=s.user;await checkStaff();await refreshCases();route()}},0)})}else renderPublic();route()}
init().catch(e=>{console.error(e);$('#queueFootnote').textContent='Unable to initialise clinic data. Check project configuration.'});
})();
